{
  "checks": [
    {
      "candidate_id": "n_pm",
      "verdict": "SUPPORT",
      "reason": "PM 是被明确指派负责检查的角色，其参与依据来自指派谓词，而非角色名称。",
      "sources": [{"quote": "请 PM 负责本次配置一致性检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_check",
      "verdict": "SUPPORT",
      "reason": "请求明确要求配置一致性检查，并以核对描述检查动作；属于主干要求。",
      "sources": [{"quote": "请 PM 负责本次配置一致性检查，核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_app",
      "verdict": "SUPPORT",
      "reason": "该文件是核对涉及的已有材料；任务仅允许读取并禁止覆盖配置，支持只读输入解释。",
      "sources": [
        {"quote": "核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "任务仅允许读取和记录差异，不得覆盖配置", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n_template",
      "verdict": "SUPPORT",
      "reason": "模板文件中的材料参与核对；只读限制支持其作为只读输入，而非生成结果。",
      "sources": [
        {"quote": "核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n_keys",
      "verdict": "SUPPORT",
      "reason": "源文明确出现关键项作为核对材料，支持 DATA 和只读输入解释；但“中的关键项”是否同时修饰两个文件存在协调范围歧义，当前身份仅对应其中一种读法。",
      "sources": [{"quote": "app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_generate",
      "verdict": "SUPPORT",
      "reason": "“并形成”明确提出产出文件的主干要求。该要求仍受仅允许读取和记录差异的限制，不能据此授权其他操作。",
      "sources": [
        {"quote": "并形成 config-consistency.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n_report",
      "verdict": "SUPPORT",
      "reason": "文件由“形成”引出，支持生成输出解释；源文未将其指定为既有输入。",
      "sources": [{"quote": "形成 config-consistency.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_read",
      "verdict": "SUPPORT",
      "reason": "读取被明确许可；许可本身不等于独立的读取义务。",
      "sources": [{"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_record",
      "verdict": "SUPPORT",
      "reason": "记录差异处于允许范围内，PERMITTED 有直接依据；此处没有独立的 REQUIRED 表述。",
      "sources": [{"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_differences",
      "verdict": "SUPPORT",
      "reason": "差异是记录动作的内容；源文没有明确将差异实体指定为文件输入、修改目标或独立生成物，UNKNOWN 保留了这一未指定状态。",
      "sources": [{"quote": "记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_overwrite",
      "verdict": "SUPPORT",
      "reason": "覆盖动作被明确禁止；FORBIDDEN 配合动作的肯定词义能够表达该禁令。",
      "sources": [{"quote": "不得覆盖配置", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "n_configuration",
      "verdict": "SUPPORT",
      "reason": "配置是被禁止覆盖的受影响材料。MODIFICATION_TARGET 表示禁止动作的目标，不构成修改许可；所给 occurrence 1 对应第二次出现的“配置”。",
      "sources": [{"quote": "配置", "clause_id": "c1", "occurrence": 1, "context_anchor": "不得覆盖配置"}]
    },
    {
      "candidate_id": "r_pm_check",
      "verdict": "SUPPORT",
      "reason": "明确要求 PM 负责检查并核对，支持实际执行参与，不是仅凭头衔推断权限。",
      "sources": [{"quote": "请 PM 负责本次配置一致性检查，核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_pm_generate",
      "verdict": "SUPPORT",
      "reason": "形成文件与负责、核对共享指派给 PM 的主语；PM 是执行参与者而非文件接收人。",
      "sources": [{"quote": "请 PM 负责本次配置一致性检查，核对 app-config.yaml 与模板文件中的关键项，并形成 config-consistency.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_check_keys",
      "verdict": "SUPPORT",
      "reason": "核对直接支配后续材料，支持关键项作为检查对象；对象内部的协调范围仍需保留歧义。",
      "sources": [{"quote": "核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_keys_app",
      "verdict": "SUPPORT",
      "reason": "当“中的关键项”修饰两个并列文件时，该归属关系有依据；另一种语法读法将 app-config.yaml 与模板文件中的关键项直接并列，因此不能把本关系视为唯一确定解释。",
      "sources": [{"quote": "app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_keys_template",
      "verdict": "SUPPORT",
      "reason": "模板文件中的关键项明确具有文件内归属关系；若 n_keys 表示两文件关键项的合并集合，该关系只能表达集合内相应成员的归属，不能断言全部关键项均属于模板文件。",
      "sources": [{"quote": "模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_generate_report",
      "verdict": "SUPPORT",
      "reason": "config-consistency.md 是形成动作的直接结果。",
      "sources": [{"quote": "形成 config-consistency.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_check_generate",
      "verdict": "SUPPORT",
      "reason": "核对与形成由“并”连接，支持并列关系；未表达完成前置条件或严格执行顺序。",
      "sources": [{"quote": "核对 app-config.yaml 与模板文件中的关键项，并形成 config-consistency.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_read_record",
      "verdict": "SUPPORT",
      "reason": "读取和记录差异是许可范围中的并列操作。",
      "sources": [{"quote": "读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_record_differences",
      "verdict": "SUPPORT",
      "reason": "差异是记录的内容，THEME 绑定有直接依据。",
      "sources": [{"quote": "记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_allowed_operations",
      "verdict": "SUPPORT",
      "reason": "“任务仅允许”把整个任务的允许操作限制到读取与记录差异的集合；不能扩展为一般写入许可。",
      "sources": [{"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_forbid_overwrite",
      "verdict": "SUPPORT",
      "reason": "任务的禁令明确指向覆盖配置动作。",
      "sources": [{"quote": "任务仅允许读取和记录差异，不得覆盖配置", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_overwrite_configuration",
      "verdict": "SUPPORT",
      "reason": "配置是覆盖动作的直接对象；该关系须连同覆盖动作的 FORBIDDEN 模态解释。",
      "sources": [{"quote": "不得覆盖配置", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "x_read",
      "verdict": "SUPPORT",
      "reason": "读取是明确列举的允许操作成员。",
      "sources": [{"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "x_record",
      "verdict": "SUPPORT",
      "reason": "记录差异是明确列举的允许操作成员。",
      "sources": [{"quote": "任务仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "x_allowed_operations",
      "verdict": "SUPPORT",
      "reason": "UNION 支持表示两类允许操作组成的集合；结合 RESTRICTS 才表达“仅”的排他限制，不表示两项均独立必做。",
      "sources": [{"quote": "仅允许读取和记录差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
  "findings": [
    {
      "id": "f_scope_ambiguity",
      "kind": "AMBIGUITY_COLLAPSED",
      "candidate_ids": ["n_keys", "r_check_keys", "r_keys_app", "r_keys_template"],
      "sources": [{"quote": "核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "图仅保留“核对两个文件中的关键项”的共享修饰读法，未保留“核对 app-config.yaml 与模板文件中的关键项”的直接并列读法。两者对 app-config.yaml 是否被限定到关键项有不同边界。与此同时，一个合并的关键项节点分别 PART_OF 两文件，未区分各文件成员归属与整个集合归属。现有支持不能消除这些范围问题。"
    }
  ],
  "coverage": [
    {
      "region_id": "c1",
      "disposition": "AMBIGUOUS",
      "candidate_ids": [
        "n_pm", "n_check", "n_app", "n_template", "n_keys", "n_generate",
        "n_report", "n_read", "n_record", "n_differences", "n_overwrite",
        "n_configuration", "r_pm_check", "r_pm_generate", "r_check_keys",
        "r_keys_app", "r_keys_template", "r_generate_report",
        "r_check_generate", "r_read_record", "r_record_differences",
        "r_allowed_operations", "r_forbid_overwrite",
        "r_overwrite_configuration", "x_read", "x_record",
        "x_allowed_operations"
      ],
      "reason": "区域中的角色参与、检查要求、文件产出要求、排他许可范围和覆盖禁令均有候选表达；但核对材料的协调范围及合并关键项节点的归属尚未可靠保留。形成文件仍受仅允许读取和记录差异约束，不能由产出要求推导额外操作许可。"
    }
  ],
  "additional_candidates": {
    "nodes": [],
    "relations": [],
    "expressions": [],
    "unresolved": [
      {
        "id": "u_key_scope",
        "kind": "UNRESOLVED_SCOPE",
        "alternatives": [
          "“中的关键项”共同修饰 app-config.yaml 与模板文件，核对范围是两文件各自的关键项。",
          "app-config.yaml 与“模板文件中的关键项”直接并列，源文未将 app-config.yaml 的核对范围明确限定为其中关键项。"
        ],
        "sources": [{"quote": "核对 app-config.yaml 与模板文件中的关键项", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
        "reason": "并列结构允许不同修饰范围；当前图没有竞争解释。保留歧义不改变源文对只读、记录差异及禁止覆盖的明确限制。"
      }
    ]
  }
}
